-- ====================================================================
-- SCRIPT KHỞI TẠO CƠ SỞ DỮ LIỆU POSTGRESQL CHUẨN CHO KHO LƯU TRỮ 'tai-lieu'
-- Khoa Vi Sinh - Bệnh Viện Đa Khoa Đức Giang
-- ====================================================================

-- 1. XÓA CÁC BẢNG DỮ LIỆU CŨ CỦA DỰ ÁN TRƯỚC
DROP TABLE IF EXISTS public.tasks CASCADE;
DROP TABLE IF EXISTS public.employees CASCADE;
DROP TABLE IF EXISTS public.trainings CASCADE;
DROP TABLE IF EXISTS public.courses CASCADE;
DROP TABLE IF EXISTS public.students CASCADE;

-- 2. TẠO BẢNG 'documents' QUẢN LÝ KHO TÀI LIỆU SUPABASE STORAGE
CREATE TABLE IF NOT EXISTS public.documents (
    id BIGSERIAL PRIMARY KEY,
    code VARCHAR(50) NOT NULL,
    title TEXT NOT NULL,
    category VARCHAR(100) NOT NULL,
    type VARCHAR(100) NOT NULL,
    year INT DEFAULT 2024,
    filename TEXT NOT NULL,
    storage_key TEXT NOT NULL,
    storage_url TEXT,
    file_format VARCHAR(20) DEFAULT 'pdf',
    file_size_formatted VARCHAR(50),
    department TEXT DEFAULT 'Khoa Vi Sinh • BVĐK Đức Giang',
    lead TEXT DEFAULT 'BS.CK2. Đào Quang Trung',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. BẬT BẢO MẬT RLS VÀ PHÂN QUYỀN TRUY CẬP CHO WEBAPP
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Cho phep toan quyen tren documents" ON public.documents;
CREATE POLICY "Cho phep toan quyen tren documents"
ON public.documents FOR ALL
USING (true)
WITH CHECK (true);

-- 4. BẬT QUYỀN TRUY CẬP BUCKET STORAGE 'tai-lieu'
DROP POLICY IF EXISTS "Allow public access tai-lieu" ON storage.objects;
DROP POLICY IF EXISTS "Cho phep tai len va xem file tai-lieu" ON storage.objects;
CREATE POLICY "Cho phep tai len va xem file tai-lieu"
ON storage.objects FOR ALL
USING ( bucket_id = 'tai-lieu' )
WITH CHECK ( bucket_id = 'tai-lieu' );

-- 5. NẠP (SEED) 114 QUY TRÌNH XÉT NGHIỆM VI SINH VÀO CSDL
